+  // either header file.
+  const onCartClick = (e?: React.SyntheticEvent<HTMLElement>): void => {
+    cartDrawer.onOpen(e?.currentTarget ?? null);
+
+    // Close the mobile nav drawer if it happened to be open — unrelated to the cart drawer,
+    // unchanged from this handler's pre-existing behaviour.
     onClose();
   };

