/*
 * Tests for the Zimmermann-added contract in product-view/index.tsx.
 *
 * Covers:
 *   - ZimmSizeSelector render (present / absent based on variationAttributes)
 *   - showActionButtons=false suppressing the Add to Bag button when no size attr is present
 *   - isSelectedSizeOOS → ariaDisabled on the inline ZimmButton
 *   - handleAddToBag → setHasAddToBagError → showError on ZimmSizeSelector
 *
 * Architecture note on showActionButtons vs the inline ZimmButton:
 *   showActionButtons=false suppresses the sticky-mobile CTA bar and the desktop
 *   renderActionButtons() box. It does NOT suppress the ZimmSizeSelector or the ZimmButton
 *   rendered inline inside the variationAttributes.map() size branch. That inline pair is
 *   the Add-to-Bag the PDP uses (showActionButtons=false is the PDP flag). Tests that
 *   exercise the inline button therefore pass showActionButtons={false} to prevent the
 *   sticky bar from adding a second data-testid="zimm-add-to-bag" match.
 */

import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import ProductView from './index';
import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import { useCartDrawer } from 'app/hooks/useCartDrawer';

// ─── Module-level mocks ───────────────────────────────────────────────────────

// react-router-dom: ProductView calls useLocation() for URL colour params and
// pathname-based effect cleanup.
vi.mock('react-router-dom', () => ({
  useLocation: vi.fn(() => ({ search: '', pathname: '/product/test-product' })),
}));

// react-intl: stub useIntl so formatMessage returns defaultMessage; stub
// FormattedMessage to render its defaultMessage prop directly.
vi.mock('react-intl', async (importOriginal) => {
  const actual = await importOriginal<typeof import('react-intl')>();
  return {
    ...actual,
    useIntl: vi.fn(() => ({
      formatMessage: (msg: { defaultMessage?: string }) => msg.defaultMessage ?? '',
    })),
    FormattedMessage: ({ defaultMessage }: { defaultMessage: string }) => <>{defaultMessage}</>,
  };
});

// @salesforce/retail-react-app/app/components/shared/ui re-exports Chakra UI.
// Stubbed with plain HTML so no real Chakra theme/provider is needed.
vi.mock('@salesforce/retail-react-app/app/components/shared/ui', () => ({
  Flex: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  // SFCC-315 — forwardRef (unlike the other plain-HTML stubs here) because product-view now
  // refs its Add to Bag wrapper (addToBagTriggerRef) to query the real <button> inside it at
  // click time — see that ref's own comment in index.tsx for why. The real Chakra Box already
  // is forwardRef; this mock needs to match that one real capability to stay testable.
  Box: React.forwardRef<HTMLDivElement, React.PropsWithChildren>(function Box({ children }, ref) {
    return <div ref={ref}>{children}</div>;
  }),
  VStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  HStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  Heading: ({ children }: React.PropsWithChildren) => <h2>{children}</h2>,
  Button: ({
    children,
    onClick,
    disabled,
    isLoading,
  }: React.PropsWithChildren<{
    onClick?: React.MouseEventHandler;
    disabled?: boolean;
    isLoading?: boolean;
  }>) => (
    <button onClick={onClick} disabled={disabled ?? isLoading}>
      {children}
    </button>
  ),
  Skeleton: ({ children }: React.PropsWithChildren) => <>{children}</>,
  Text: ({ children }: React.PropsWithChildren) => <span>{children}</span>,
  Fade: ({ children }: React.PropsWithChildren) => <>{children}</>,
  Stack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  Radio: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  RadioGroup: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  // useTheme is called for `theme.shadows.top` in the sticky mobile bar.
  useTheme: vi.fn(() => ({ shadows: { top: 'none' } })),
}));

// useCurrency and useDerivedProduct live in this barrel.
vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
  useCurrency: vi.fn(() => ({ currency: 'AUD' })),
  useDerivedProduct: vi.fn(),
}));

// ProductView now calls useSafeHref() (regional link prefixing fix for related-swatch hrefs) —
// mocked at its own module boundary (identity function) rather than reaching through to the real
// useMultiSite/MultiSiteContext chain, which has a known JSX-in-.js Vitest parse failure. See
// zimmLink/index.test.tsx's identical comment; this suite doesn't assert on prefixing itself
// (that's useSafeHref.test.ts's job), just needs ProductView to render without it throwing.
vi.mock('app/hooks/useSafeHref', () => ({
  useSafeHref: () => (href: string) => href,
}));

// SFCC-315 — replaces the removed useAddToCartModalContext mock. No default implementation in
// the factory itself: the outer beforeEach below establishes a fresh default via
// mockUseCartDrawer.mockReturnValue(...) before every test (mirroring mockDerivedProduct()'s own
// per-test reset), and the SFCC-315 suite further down overrides it per-test to capture onOpen.
vi.mock('app/hooks/useCartDrawer', () => ({
  useCartDrawer: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/constants', () => ({
  STORE_LOCATOR_IS_ENABLED: false,
  API_ERROR_MESSAGE: { defaultMessage: 'An error occurred.', id: 'app.error.api' },
}));

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: vi.fn(() => null),
}));

// useShopperBasketsV2Mutation is called twice (createBasket, addItemToBasket).
vi.mock('@salesforce/commerce-sdk-react', () => ({
  useShopperBasketsV2Mutation: vi.fn(() => ({ mutateAsync: vi.fn() })),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-sf-payments', () => ({
  useSFPayments: vi.fn(() => ({ confirmingBasket: false })),
  useExpressCheckoutEnabled: vi.fn(() => ({ pdp: false })),
  EXPRESS_BUY_NOW: 'EXPRESS_BUY_NOW',
}));

vi.mock('@salesforce/retail-react-app/app/components/image-gallery', () => ({
  default: () => <div data-testid="image-gallery" />,
  Skeleton: () => <div data-testid="image-gallery-skeleton" />,
}));

// SFCC-731 — Zimmermann gallery (imageSize="md" path). Statically imported by index.tsx, so it
// evaluates at module-load time regardless of the showImageGallery prop these tests use to skip
// the gallery — and ZimmGalleryOverlay itself statically imports ZimmColourSwatchGroup, which
// pulls in react-router-dom's real Link (this file only mocks useLocation). Mocked to keep these
// tests scoped to the Zimmermann contract this file documents (see header comment), not gallery
// rendering — covered by ZimmProductGallery's/ZimmGalleryOverlay's own test suites instead.
vi.mock('../ui-kits/organisms/zimmProductGallery', () => ({
  ZimmProductGallery: () => <div data-testid="zimm-product-gallery" />,
}));
vi.mock('../ui-kits/organisms/zimmGalleryOverlay', () => ({
  ZimmGalleryOverlay: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/breadcrumb', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/link', () => ({
  default: ({ children }: React.PropsWithChildren) => <span>{children}</span>,
}));

// withRegistration wraps Button; stub as a passthrough HOC.
vi.mock('@salesforce/retail-react-app/app/components/with-registration', () => ({
  default: (Component: React.ComponentType<unknown>) => Component,
}));

// ZimmWishlistAuthDrawer pulls in use-auth-modal.js (SFCC JSX-in-.js), which Vitest's Vite
// transform can't parse — same root cause as the ZimmIcon / icons barrel mocks elsewhere (see
// testing.md). Mocked as a transparent wrapper — passes onAuthSuccess as onClick to the child,
// matching the pattern in header/rightBar/index.test.tsx.
vi.mock('app/components/ui-kits/organisms/zimmWishlistAuthDrawer', () => ({
  ZimmWishlistAuthDrawer: ({ children, onAuthSuccess }: { children: React.ReactElement; onAuthSuccess?: () => void }) =>
    React.cloneElement(children, { onClick: onAuthSuccess }),
}));

// SFCC-434 — ZimmWishlistBadge (the header wishlist badge) renders ZimmIcon, which
// imports the base SFCC icons barrel and throws under Vitest — documented gap, see testing.md's
// "Known gap: ZimmIcon throws under Vitest". Mocked at the smallest surface rather than mocking
// ZimmWishlistBadge itself, matching testing.md's own example.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/responsive', () => ({
  HideOnDesktop: ({ children }: React.PropsWithChildren) => <>{children}</>,
  HideOnMobile: ({ children }: React.PropsWithChildren) => <>{children}</>,
}));

vi.mock('@salesforce/retail-react-app/app/components/quantity-picker', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: vi.fn(() => vi.fn()),
}));

vi.mock('@salesforce/retail-react-app/app/components/display-price', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/swatch-group/swatch', () => ({
  default: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
}));

vi.mock('@salesforce/retail-react-app/app/components/swatch-group', () => ({
  default: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
}));

vi.mock('@salesforce/retail-react-app/app/utils/product-utils', () => ({
  getPriceData: vi.fn(() => ({ currentPrice: 100 })),
}));

vi.mock('@salesforce/retail-react-app/app/components/product-tile/promo-callout', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/sf-payments-express-buttons', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets', () => ({
  useCleanupTemporaryBaskets: vi.fn(() => vi.fn()),
}));

vi.mock('@salesforce/retail-react-app/app/components/loading-spinner', () => ({
  default: () => null,
}));

// ZimmSizeSelector — expose showError and errorMessage via data attributes so tests can assert on them.
vi.mock('app/components/ui-kits/molecules/zimmSizeSelector', () => ({
  ZimmSizeSelector: ({ showError, errorMessage }: { showError?: boolean; errorMessage?: string }) => (
    <div
      data-testid="zimm-size-selector"
      data-show-error={String(!!showError)}
      data-error-message={errorMessage ?? ''}
    />
  ),
}));

// ZimmButton — expose ariaDisabled via aria-disabled; forward onClick so handleAddToBag fires.
vi.mock('app/components/ui-kits/atoms/zimmButton', () => ({
  ZimmButton: ({
    label,
    ariaDisabled,
    onClick,
    disabled,
  }: {
    label: string;
    ariaDisabled?: boolean;
    onClick?: () => void;
    disabled?: boolean;
  }) => (
    <button
      data-testid="zimm-add-to-bag"
      aria-disabled={ariaDisabled === true ? 'true' : undefined}
      onClick={onClick}
      disabled={disabled}
    >
      {label}
    </button>
  ),
}));

// ─── Helpers ──────────────────────────────────────────────────────────────────

const mockUseDerivedProduct = vi.mocked(useDerivedProduct);
const mockUseToast = vi.mocked(useToast);
const mockUseCartDrawer = vi.mocked(useCartDrawer);

/** Seeds useDerivedProduct with sensible defaults; variationAttributes defaults to empty. */
function mockDerivedProduct(overrides: Record<string, unknown> = {}) {
  mockUseDerivedProduct.mockReturnValue({
    showLoading: false,
    showInventoryMessage: false,
    inventoryMessage: '',
    quantity: 1,
    minOrderQuantity: 1,
    setQuantity: vi.fn(),
    variant: null,
    variationParams: {},
    variationAttributes: [],
    stockLevel: 10,
    stepQuantity: 1,
    isOutOfStock: false,
    unfulfillable: false,
    isSelectedStoreOutOfStock: false,
    selectedStore: null,
    ...overrides,
  });
}

/**
 * Minimal product object that includes a size variation attribute.
 * `sizeValues` controls which sizes are orderable — used by `isSelectedSizeOOS`.
 */
function buildProductWithSize(
  sizeValues = [
    { value: 'S', orderable: true },
    { value: 'M', orderable: true },
    { value: 'L', orderable: false }, // intentionally OOS for test 4
  ],
) {
  return {
    id: 'test-jacket',
    name: 'Test Jacket',
    type: { item: true },
    currency: 'AUD',
    inventory: { orderable: true, backorderable: false },
    variationAttributes: [{ id: 'size', values: sizeValues }],
    imageGroups: [],
  };
}

/**
 * Colour variation attribute as shaped by useDerivedProduct.
 */
const derivedColourAttr = {
  id: 'color',
  name: 'Colour',
  selectedValue: undefined,
  values: [{ value: 'ivory', name: 'Ivory', orderable: true }],
};

/**
 * Size variation attribute as shaped by useDerivedProduct — this controls which
 * attribute block ProductView renders, independent of the product prop.
 */
const derivedSizeAttr = {
  id: 'size',
  name: 'Size',
  selectedValue: undefined,
  values: [
    { value: 'S', name: 'S', orderable: true },
    { value: 'M', name: 'M', orderable: true },
    { value: 'L', name: 'L', orderable: false },
  ],
};

/** Suppresses image gallery, delivery options, and quantity picker across all tests. */
const quietProps = {
  showImageGallery: false,
  showDeliveryOptions: false,
  showQuantityPicker: false,
} as const;

// jsdom implements no scrollIntoView at all (not this-project-specific — a well-known jsdom
// gap). Not reachable before this suite's own SFCC-315 change: the Box mock above was a plain,
// non-forwardRef function component, so validateAndShowError's pre-existing (unrelated)
// `errorContainerRef.current?.scrollIntoView(...)` call always found `.current === null` and the
// optional-chaining short-circuited it. Making Box forward its ref (needed for
// addToBagTriggerRef, above) makes errorContainerRef attach for real too, so the call is now
// actually reached — an unhandled rejection inside handleAddToBag's fire-and-forget
// `void handleAddToBag()` call sites otherwise. Stubbed globally for this file rather than in
// vitest.setup.ts (Tier 1 test config, out of this step's scope) since this file is the one
// whose own mock change newly exposes it.
window.HTMLElement.prototype.scrollIntoView = vi.fn();

// ─── Tests ────────────────────────────────────────────────────────────────────

describe('ProductView — Zimmermann additions', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockDerivedProduct();
    // SFCC-315 — fresh default before every test, mirroring mockDerivedProduct()'s own reset;
    // the SFCC-315 suite further down overrides this per-test to capture onOpen.
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: vi.fn(),
      onClose: vi.fn(),
      triggerRef: { current: null },
    });
  });

  test('renders ZimmSizeSelector when useDerivedProduct returns a size variation attribute', () => {
    // Arrange
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    // Act
    render(<ProductView product={buildProductWithSize()} addToCart={vi.fn()} {...quietProps} />);

    // Assert — ZimmSizeSelector appears in the size attribute branch of variationAttributes.map()
    expect(screen.getByTestId('zimm-size-selector')).toBeInTheDocument();
  });

  test('does not render ZimmSizeSelector when variationAttributes has no size entry', () => {
    // Arrange — variationAttributes defaults to [] in mockDerivedProduct
    render(
      <ProductView
        product={{
          id: 'plain',
          name: 'Plain Product',
          type: { item: true },
          inventory: { orderable: true },
          variationAttributes: [],
          imageGroups: [],
        }}
        addToCart={vi.fn()}
        {...quietProps}
      />,
    );

    // Assert
    expect(screen.queryByTestId('zimm-size-selector')).not.toBeInTheDocument();
  });

  test('showActionButtons=false suppresses Add to Bag when there is no size attribute', () => {
    // When there is no size attribute, the only path that renders a ZimmButton is
    // renderActionButtons(), which is called from the desktop box and the sticky mobile
    // bar — both gated by showActionButtons. With showActionButtons=false, neither fires.
    render(
      <ProductView
        product={{
          id: 'plain',
          name: 'Plain Product',
          type: { item: true },
          inventory: { orderable: true },
          variationAttributes: [],
          imageGroups: [],
        }}
        addToCart={vi.fn()}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.queryByTestId('zimm-add-to-bag')).not.toBeInTheDocument();
  });

  test('inline ZimmButton receives aria-disabled="true" when the selected size is OOS', () => {
    // Arrange
    // isSelectedSizeOOS reads product.variationAttributes (L is orderable:false) and
    // effectiveSizeValue. controlledVariationValues forces effectiveSizeValue to 'L'.
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    // Act
    // showActionButtons=false ensures only the inline ZimmButton (from the size block)
    // renders — the sticky mobile bar is suppressed, so getByTestId finds exactly one match.
    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        controlledVariationValues={{ size: 'L' }}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    // Assert
    const button = screen.getByTestId('zimm-add-to-bag');
    expect(button).toHaveAttribute('aria-disabled', 'true');
  });

  test('sets aria-disabled and shows max-qty message when basket already holds the max', () => {
    // Arrange
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={2}
        basketProductItems={[{ productId: 'sku-s', quantity: 2 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    const button = screen.getByTestId('zimm-add-to-bag');
    expect(button).toHaveAttribute('aria-disabled', 'true');
    const sizeSelector = screen.getByTestId('zimm-size-selector');
    expect(sizeSelector).toHaveAttribute('data-show-error', 'true');
    expect(sizeSelector).toHaveAttribute('data-error-message', 'Maximum purchase quantity reached for this size');
  });

  test('does not restrict Add to Bag when a different size variant has reached max', () => {
    // Arrange — basket has 2 of sku-m, selected size is sku-s (AC #3)
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={2}
        basketProductItems={[{ productId: 'sku-m', quantity: 2 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.getByTestId('zimm-add-to-bag')).not.toHaveAttribute('aria-disabled', 'true');
    const sizeSelector = screen.getByTestId('zimm-size-selector');
    expect(sizeSelector).not.toHaveAttribute('data-error-message', 'Maximum purchase quantity reached for this size');
  });

  test('does not restrict Add to Bag when maxOrderQuantity is null', () => {
    // Arrange — no max configured; basket qty irrelevant (AC #4)
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={null}
        basketProductItems={[{ productId: 'sku-s', quantity: 99 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.getByTestId('zimm-add-to-bag')).not.toHaveAttribute('aria-disabled', 'true');
    const sizeSelector = screen.getByTestId('zimm-size-selector');
    expect(sizeSelector).not.toHaveAttribute('data-error-message', 'Maximum purchase quantity reached for this size');
  });

  test('does not show max-qty message when basket qty is below the max', () => {
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={3}
        basketProductItems={[{ productId: 'sku-s', quantity: 1 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.getByTestId('zimm-size-selector')).not.toHaveAttribute(
      'data-error-message',
      'Maximum purchase quantity reached for this size',
    );
  });

  test('shows colour prompt (not size error) when colour is missing but size is already selected', async () => {
    // Arrange — both colour and size attrs present; colour NOT in variationParams (none selected).
    mockDerivedProduct({
      variationAttributes: [derivedColourAttr, derivedSizeAttr],
      variationParams: { size: '6' }, // colour absent → isColourMissing=true
      variant: null, // no complete variant without colour → validateOrderability returns false
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        controlledVariationValues={{ size: '6' }}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

    // Size selector must NOT show its error — colour is missing, not size.
    expect(screen.getByTestId('zimm-size-selector')).toHaveAttribute('data-show-error', 'false');
    // Colour prompt must appear.
    expect(screen.getByText('Please select a colour')).toBeInTheDocument();
  });

  test('clicking Add to Bag without selecting a size makes ZimmSizeSelector show its error state', async () => {
    // Arrange
    // No controlledVariationValues and localSizeValue starts as null → effectiveSizeValue=null.
    // handleAddToBag detects hasSizeAttribute=true and !effectiveSizeValue → setHasAddToBagError(true),
    // which flows into ZimmSizeSelector as showError=true.
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    render(
      <ProductView product={buildProductWithSize()} addToCart={vi.fn()} showActionButtons={false} {...quietProps} />,
    );

    const sizeSelector = screen.getByTestId('zimm-size-selector');
    const button = screen.getByTestId('zimm-add-to-bag');

    // Assert initial state — no error yet
    expect(sizeSelector).toHaveAttribute('data-show-error', 'false');

    // Act
    await userEvent.click(button);

    // Assert — showError prop is now true after the failed attempt
    expect(screen.getByTestId('zimm-size-selector')).toHaveAttribute('data-show-error', 'true');
  });

  test('shows colour prompt in errorContainerRef for a colour-only product with no size attribute', async () => {
    // Colour-only product — no size branch renders, so the inline alert inside the size branch
    // never mounts. The colour alert must fall back to the errorContainerRef box.
    // showActionButtons=true is required: renderActionButtons() is the only path that renders
    // Add to Bag when there is no size attribute, and it is gated by showActionButtons.
    // Both the desktop box and the sticky mobile bar call renderActionButtons(), so
    // getAllByTestId finds two matches — click the first.
    mockDerivedProduct({
      variationAttributes: [derivedColourAttr],
      variationParams: {}, // colour absent → isColourMissing=true
      variant: null,
    });

    render(
      <ProductView
        product={{
          id: 'colour-only',
          name: 'Colour Only Product',
          type: { item: true },
          currency: 'AUD',
          inventory: { orderable: true, backorderable: false },
          variationAttributes: [{ id: 'color', values: [{ value: 'ivory', orderable: true }] }],
          imageGroups: [],
        }}
        addToCart={vi.fn()}
        showActionButtons={true}
        {...quietProps}
      />,
    );

    const [addToBagBtn] = screen.getAllByTestId('zimm-add-to-bag');
    await userEvent.click(addToBagBtn);

    expect(screen.queryByTestId('zimm-size-selector')).not.toBeInTheDocument();
    expect(screen.getByText('Please select a colour')).toBeInTheDocument();
  });

  describe('SFCC-315 — Add to Bag opens the cart drawer, not the base AddToCartModal', () => {
    test('opens the cart drawer with the real clicked button as the AC10 focus-return trigger — the PDP add-to-bag trigger origin', async () => {
      const onCartDrawerOpen = vi.fn();
      mockUseCartDrawer.mockReturnValue({
        isOpen: false,
        onOpen: onCartDrawerOpen,
        onClose: vi.fn(),
        triggerRef: { current: null },
      });
      mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

      render(
        <ProductView
          product={buildProductWithSize()}
          addToCart={vi.fn().mockResolvedValue([{ itemId: 'sku-s' }])}
          controlledVariationValues={{ size: 'S' }}
          validateOrderability={() => true}
          showActionButtons={false}
          {...quietProps}
        />,
      );

      const button = screen.getByTestId('zimm-add-to-bag');
      await userEvent.click(button);

      // The real button itself — not a wrapper, not document.activeElement — is what AC10 must
      // return focus to. See addToBagTriggerRef's own comment in index.tsx for the mechanism
      // (wrapping Box ref + querySelector, since ZimmButton's onClick carries no event and
      // ZimmButton isn't forwardRef).
      await waitFor(() => {
        expect(onCartDrawerOpen).toHaveBeenCalledWith(button);
      });
    });

    test('does not open the cart drawer when addToCart resolves with no items added', async () => {
      const onCartDrawerOpen = vi.fn();
      mockUseCartDrawer.mockReturnValue({
        isOpen: false,
        onOpen: onCartDrawerOpen,
        onClose: vi.fn(),
        triggerRef: { current: null },
      });
      mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

      render(
        <ProductView
          product={buildProductWithSize()}
          addToCart={vi.fn().mockResolvedValue(null)}
          controlledVariationValues={{ size: 'S' }}
          validateOrderability={() => true}
          showActionButtons={false}
          {...quietProps}
        />,
      );

      await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

      expect(onCartDrawerOpen).not.toHaveBeenCalled();
    });

    test('does not open the cart drawer, and shows an error toast, when addToCart rejects', async () => {
      const onCartDrawerOpen = vi.fn();
      const showToast = vi.fn();
      mockUseCartDrawer.mockReturnValue({
        isOpen: false,
        onOpen: onCartDrawerOpen,
        onClose: vi.fn(),
        triggerRef: { current: null },
      });
      mockUseToast.mockReturnValueOnce(showToast);
      mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

      render(
        <ProductView
          product={buildProductWithSize()}
          addToCart={vi.fn().mockRejectedValue(new Error('network error'))}
          controlledVariationValues={{ size: 'S' }}
          validateOrderability={() => true}
          showActionButtons={false}
          {...quietProps}
        />,
      );

      await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

      await waitFor(() => {
        expect(showToast).toHaveBeenCalledWith(expect.objectContaining({ status: 'error' }));
      });
      expect(onCartDrawerOpen).not.toHaveBeenCalled();
    });
  });

  describe('SFCC-434 — wishlist toggle', () => {
    // imageSize defaults to 'md' (the PDP's own path), so only the desktop renderHeader() call
    // site (always mounted, just display:none-toggled — see its own comment) renders the badge.
    const simpleProduct = {
      id: 'test-jacket',
      name: 'Test Jacket',
      type: { item: true },
      currency: 'AUD',
      inventory: { orderable: true, backorderable: false },
      variationAttributes: [],
      imageGroups: [],
    };

    test('derives isInWishlist from product.id for a simple product with no variant', () => {
      // Arrange — mockDerivedProduct()'s default variant is null, matching a simple product.
      render(
        <ProductView
          product={simpleProduct}
          addToCart={vi.fn()}
          addToWishlist={vi.fn()}
          removeFromWishlist={vi.fn()}
          wishlistedProductIds={['test-jacket']}
          {...quietProps}
        />,
      );

      expect(screen.getByTestId('add-to-wishlist-button')).toHaveAttribute('aria-label', 'Remove from Wishlist');
    });

    test('disables the toggle when already wishlisted but no removeFromWishlist callback is wired', () => {
      render(
        <ProductView
          product={simpleProduct}
          addToCart={vi.fn()}
          addToWishlist={vi.fn()}
          wishlistedProductIds={['test-jacket']}
          {...quietProps}
        />,
      );

      expect(screen.getByTestId('add-to-wishlist-button')).toBeDisabled();
    });

    test('disables the toggle when not yet wishlisted but no addToWishlist callback is wired', () => {
      render(
        <ProductView
          product={simpleProduct}
          addToCart={vi.fn()}
          removeFromWishlist={vi.fn()}
          wishlistedProductIds={[]}
          {...quietProps}
        />,
      );

      expect(screen.getByTestId('add-to-wishlist-button')).toBeDisabled();
    });

    test('clicking the toggle calls addToWishlist, not removeFromWishlist, when not yet wishlisted', async () => {
      const addToWishlist = vi.fn();
      const removeFromWishlist = vi.fn();
      render(
        <ProductView
          product={simpleProduct}
          addToCart={vi.fn()}
          addToWishlist={addToWishlist}
          removeFromWishlist={removeFromWishlist}
          wishlistedProductIds={[]}
          {...quietProps}
        />,
      );

      const button = screen.getByTestId('add-to-wishlist-button');
      expect(button).not.toBeDisabled();
      await userEvent.click(button);

      expect(addToWishlist).toHaveBeenCalledTimes(1);
      expect(removeFromWishlist).not.toHaveBeenCalled();
    });

    test('clicking the toggle calls removeFromWishlist, not addToWishlist, when already wishlisted', async () => {
      const addToWishlist = vi.fn();
      const removeFromWishlist = vi.fn();
      render(
        <ProductView
          product={simpleProduct}
          addToCart={vi.fn()}
          addToWishlist={addToWishlist}
          removeFromWishlist={removeFromWishlist}
          wishlistedProductIds={['test-jacket']}
          {...quietProps}
        />,
      );

      const button = screen.getByTestId('add-to-wishlist-button');
      expect(button).not.toBeDisabled();
      await userEvent.click(button);

      expect(removeFromWishlist).toHaveBeenCalledTimes(1);
      expect(addToWishlist).not.toHaveBeenCalled();
    });

    test('shows an error toast when the wishlist mutation rejects, instead of an unhandled rejection', async () => {
      const showToast = vi.fn();
      mockUseToast.mockReturnValueOnce(showToast);
      const addToWishlist = vi.fn().mockRejectedValue(new Error('network error'));

      render(
        <ProductView
          product={simpleProduct}
          addToCart={vi.fn()}
          addToWishlist={addToWishlist}
          wishlistedProductIds={[]}
          {...quietProps}
        />,
      );

      await userEvent.click(screen.getByTestId('add-to-wishlist-button'));

      // onClick fires handleWishlistToggle() with `void` (fire-and-forget) — the click event
      // itself resolves before the async rejection/catch/showToast chain does, so this needs to
      // wait rather than assert immediately.
      await waitFor(() => {
        expect(showToast).toHaveBeenCalledWith(expect.objectContaining({ status: 'error' }));
      });
    });

    test('disables the toggle when the product has no resolvable id, even though a callback exists', () => {
      // No `id`/`productId` on the product, and mockDerivedProduct()'s default variant is null —
      // wishlistProductId resolves to undefined, so the toggle must stay disabled regardless of
      // canAddToWishlist/isProductLoading.
      render(
        <ProductView
          product={{
            name: 'No Id Product',
            type: { item: true },
            currency: 'AUD',
            inventory: { orderable: true, backorderable: false },
            variationAttributes: [],
            imageGroups: [],
          }}
          addToCart={vi.fn()}
          addToWishlist={vi.fn()}
          wishlistedProductIds={[]}
          {...quietProps}
        />,
      );

      expect(screen.getByTestId('add-to-wishlist-button')).toBeDisabled();
    });
  });
});

import { defineConfig } from 'vitest/config';
import path from 'path';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: ['./vitest.setup.ts'],
    include: ['overrides/**/*.test.ts', 'overrides/**/*.test.tsx'],
    passWithNoTests: true,
    coverage: {
      provider: 'v8',
      // Force-includes every file under overrides/ at 0% if no test ever
      // imports it — without this, coverage only reports on the files the
      // 16 (as of 2026-08-26) existing test files happen to import, which
      // reads as a misleadingly high percentage of a much smaller universe
      // than "overrides/" as a whole (added at the developer's explicit
      // request for whole-tree visibility, not just tested-file visibility).
      all: true,
      include: ['overrides/**/*.{ts,tsx}'],
      exclude: [
        'overrides/**/*.test.{ts,tsx}',
        'overrides/**/*.stories.{ts,tsx}',
        'overrides/**/*.css.ts',
        'overrides/**/*.d.ts',
      ],
      reporter: ['text', 'json-summary', 'html'],
    },
  },
  resolve: {
    // Keep in sync with babel.config.js, tsconfig.json, .storybook/main.js
    // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
    alias: {
      '~': path.resolve(__dirname),
      app: path.resolve(__dirname, 'overrides/app'),
      // @salesforce/commerce-sdk-react@5.2.0's published package.json declares
      // main: "dist/index.js", but the published tarball has no dist/ at all —
      // the real entry file is index.js at the package root (confirmed by
      // unpacking the npm tarball directly; same defect persists through at
      // least 5.4.0). Node/webpack resolve this fine because their module
      // resolution falls back to a package's root index.js when `main` doesn't
      // exist; Vite/Vitest's resolver has no such fallback and fails with
      // "Failed to resolve entry for package". The same broken-`main` defect
      // also breaks Vite/Vitest's resolution of this package's subpath exports
      // (`/components`, `/page-designer`) even though each has a real
      // index.js on disk and Node/webpack resolve them fine — an earlier
      // revision of this comment claimed subpaths "resolve normally,
      // untouched by this alias"; that was wrong, disproven when
      // overrides/app/components/_app/index.tsx (SFCC-863) became the first
      // file in overrides/ to import either subpath and its test failed to
      // resolve them. Add a new exact-match entry here for each subpath as
      // one gets a real consumer, rather than trying to express this as a
      // single prefix/RegExp alias.
      // Order matters: Vite's alias matching treats a bare-specifier key as a prefix match
      // too (`importee === key || importee.startsWith(key + '/')`), so the subpath entries
      // must come before the bare '@salesforce/commerce-sdk-react' entry below or that
      // broader entry wins first and mis-resolves the subpath.
      '@salesforce/commerce-sdk-react/components': path.resolve(
        __dirname,
        'node_modules/@salesforce/commerce-sdk-react/components/index.js',
      ),
      '@salesforce/commerce-sdk-react/page-designer': path.resolve(
        __dirname,
        'node_modules/@salesforce/commerce-sdk-react/page-designer/index.js',
      ),
      '@salesforce/commerce-sdk-react': path.resolve(__dirname, 'node_modules/@salesforce/commerce-sdk-react/index.js'),
    },
  },
});

