/*
 * TESTER-6 THROWAWAY INTEGRATION ATTEMPT — SFCC-11 plan §9 pass criterion 12 regression check.
 *
 * Goal: render the BASE (unoverridden) `product-view-modal` from
 * node_modules/@salesforce/retail-react-app, with `@salesforce/retail-react-app/app/components/
 * product-view` swapped (via vi.mock) for OUR override at overrides/app/components/product-view
 * — simulating what the real webpack ccExtensibility resolver does in the shipped app (Vitest
 * itself does not run that resolver) — and prove that clicking Add to Bag inside that base modal
 * reaches our `useCartDrawer()` hook's `onOpen`, not the removed `useAddToCartModalContext`.
 *
 * Mock recipe below is adapted directly from the real, already-committed
 * overrides/app/components/product-view/index.test.tsx (same repo, same override, same day) —
 * every mock there exists to stop ProductView crashing on render; this file needs the identical
 * set since it renders the exact same component, plus a handful of new ones for
 * product-view-modal's own additional imports (Modal parts, useProductViewModal).
 */

import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

// ─── The swap under test: base product-view import → our override ─────────────
// This is the one line doing the work AGENTS.md's ccExtensibility mechanism does for real in the
// shipped app. product-view-modal/index.jsx imports ProductView from this exact specifier.
vi.mock('@salesforce/retail-react-app/app/components/product-view', async () => {
  return await import('app/components/product-view');
});

// ─── Same module-level mocks as overrides/app/components/product-view/index.test.tsx ──────────

vi.mock('react-router-dom', () => ({
  useLocation: vi.fn(() => ({ search: '', pathname: '/product/test-product' })),
}));

vi.mock('react-intl', async (importOriginal) => {
  const actual = await importOriginal<typeof import('react-intl')>();
  return {
    ...actual,
    useIntl: vi.fn(() => ({
      formatMessage: (msg: { defaultMessage?: string }) => msg.defaultMessage ?? '',
    })),
    FormattedMessage: ({ defaultMessage }: { defaultMessage: string }) => <>{defaultMessage}</>,
  };
});

// Extended vs. the original — adds Modal/ModalOverlay/ModalContent/ModalCloseButton/ModalBody,
// which product-view-modal/index.jsx itself imports from this same barrel.
vi.mock('@salesforce/retail-react-app/app/components/shared/ui', () => ({
  Flex: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  Box: React.forwardRef<HTMLDivElement, React.PropsWithChildren>(function Box({ children }, ref) {
    return <div ref={ref}>{children}</div>;
  }),
  VStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  HStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  Heading: ({ children }: React.PropsWithChildren) => <h2>{children}</h2>,
  Button: ({
    children,
    onClick,
    disabled,
    isLoading,
  }: React.PropsWithChildren<{
    onClick?: React.MouseEventHandler;
    disabled?: boolean;
    isLoading?: boolean;
  }>) => (
    <button onClick={onClick} disabled={disabled ?? isLoading}>
      {children}
    </button>
  ),
  Skeleton: ({ children }: React.PropsWithChildren) => <>{children}</>,
  Text: ({ children }: React.PropsWithChildren) => <span>{children}</span>,
  Fade: ({ children }: React.PropsWithChildren) => <>{children}</>,
  Stack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  Radio: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  RadioGroup: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
  useTheme: vi.fn(() => ({ shadows: { top: 'none' } })),
  // New for product-view-modal — plain passthrough stand-ins, Modal only renders when isOpen.
  Modal: ({ children, isOpen }: React.PropsWithChildren<{ isOpen?: boolean }>) =>
    isOpen ? <div data-testid="modal-root">{children}</div> : null,
  ModalOverlay: () => <div data-testid="modal-overlay" />,
  ModalContent: ({ children }: React.PropsWithChildren) => <div data-testid="modal-content">{children}</div>,
  ModalCloseButton: () => <button data-testid="modal-close">close</button>,
  ModalBody: ({ children }: React.PropsWithChildren) => <div data-testid="modal-body">{children}</div>,
}));

vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
  useCurrency: vi.fn(() => ({ currency: 'AUD' })),
  useDerivedProduct: vi.fn(),
}));

vi.mock('app/hooks/useSafeHref', () => ({
  useSafeHref: () => (href: string) => href,
}));

// The hook under regression test — spy on onOpen to prove the wiring reaches it.
vi.mock('app/hooks/useCartDrawer', () => ({
  useCartDrawer: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/constants', () => ({
  STORE_LOCATOR_IS_ENABLED: false,
  API_ERROR_MESSAGE: { defaultMessage: 'An error occurred.', id: 'app.error.api' },
}));

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: vi.fn(() => null),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  useShopperBasketsV2Mutation: vi.fn(() => ({ mutateAsync: vi.fn() })),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-sf-payments', () => ({
  useSFPayments: vi.fn(() => ({ confirmingBasket: false })),
  useExpressCheckoutEnabled: vi.fn(() => ({ pdp: false })),
  EXPRESS_BUY_NOW: 'EXPRESS_BUY_NOW',
}));

vi.mock('@salesforce/retail-react-app/app/components/image-gallery', () => ({
  default: () => <div data-testid="image-gallery" />,
  Skeleton: () => <div data-testid="image-gallery-skeleton" />,
}));

vi.mock('app/components/ui-kits/organisms/zimmProductGallery', () => ({
  ZimmProductGallery: () => <div data-testid="zimm-product-gallery" />,
}));
vi.mock('app/components/ui-kits/organisms/zimmGalleryOverlay', () => ({
  ZimmGalleryOverlay: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/breadcrumb', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/link', () => ({
  default: ({ children }: React.PropsWithChildren) => <span>{children}</span>,
}));

vi.mock('@salesforce/retail-react-app/app/components/with-registration', () => ({
  default: (Component: React.ComponentType<unknown>) => Component,
}));

vi.mock('app/components/ui-kits/organisms/zimmWishlistAuthDrawer', () => ({
  ZimmWishlistAuthDrawer: ({ children, onAuthSuccess }: { children: React.ReactElement; onAuthSuccess?: () => void }) =>
    React.cloneElement(children, { onClick: onAuthSuccess }),
}));

vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/responsive', () => ({
  HideOnDesktop: ({ children }: React.PropsWithChildren) => <>{children}</>,
  HideOnMobile: ({ children }: React.PropsWithChildren) => <>{children}</>,
}));

vi.mock('@salesforce/retail-react-app/app/components/quantity-picker', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: vi.fn(() => vi.fn()),
}));

vi.mock('@salesforce/retail-react-app/app/components/display-price', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/swatch-group/swatch', () => ({
  default: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
}));

vi.mock('@salesforce/retail-react-app/app/components/swatch-group', () => ({
  default: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
}));

vi.mock('@salesforce/retail-react-app/app/utils/product-utils', () => ({
  getPriceData: vi.fn(() => ({ currentPrice: 100 })),
}));

vi.mock('@salesforce/retail-react-app/app/components/product-tile/promo-callout', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/sf-payments-express-buttons', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets', () => ({
  useCleanupTemporaryBaskets: vi.fn(() => vi.fn()),
}));

vi.mock('@salesforce/retail-react-app/app/components/loading-spinner', () => ({
  default: () => null,
}));

vi.mock('app/components/ui-kits/molecules/zimmSizeSelector', () => ({
  ZimmSizeSelector: ({ showError, errorMessage }: { showError?: boolean; errorMessage?: string }) => (
    <div
      data-testid="zimm-size-selector"
      data-show-error={String(!!showError)}
      data-error-message={errorMessage ?? ''}
    />
  ),
}));

vi.mock('app/components/ui-kits/atoms/zimmButton', () => ({
  ZimmButton: ({
    label,
    ariaDisabled,
    onClick,
    disabled,
  }: {
    label: string;
    ariaDisabled?: boolean;
    onClick?: () => void;
    disabled?: boolean;
  }) => (
    <button
      data-testid="zimm-add-to-bag"
      aria-disabled={ariaDisabled === true ? 'true' : undefined}
      onClick={onClick}
      disabled={disabled}
    >
      {label}
    </button>
  ),
}));

// New for this file — product-view-modal's own additional dependency.
vi.mock('@salesforce/retail-react-app/app/hooks/use-product-view-modal', () => ({
  useProductViewModal: vi.fn(() => ({
    product: {
      id: 'test-jacket',
      name: 'Test Jacket',
      type: { item: true },
      currency: 'AUD',
      inventory: { orderable: true, backorderable: false },
      variationAttributes: [{ id: 'size', values: [{ value: 'S', orderable: true }] }],
      imageGroups: [],
    },
    isFetching: false,
  })),
}));

window.HTMLElement.prototype.scrollIntoView = vi.fn();

// ─── Imports that must come after the mocks above ──────────────────────────────
import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
import { useCartDrawer } from 'app/hooks/useCartDrawer';
// The BASE, unoverridden modal — imported straight from node_modules, exactly as
// bonus-product-view-modal's own sibling does, and exactly as any real SFCC page would.
import ProductViewModal from '@salesforce/retail-react-app/app/components/product-view-modal';

const mockUseDerivedProduct = vi.mocked(useDerivedProduct);
const mockUseCartDrawer = vi.mocked(useCartDrawer);

const derivedSizeAttr = {
  id: 'size',
  name: 'Size',
  selectedValue: undefined,
  values: [{ value: 'S', name: 'S', orderable: true }],
};

describe('TESTER-6 regression: base product-view-modal + our product-view override', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockUseDerivedProduct.mockReturnValue({
      showLoading: false,
      showInventoryMessage: false,
      inventoryMessage: '',
      quantity: 1,
      minOrderQuantity: 1,
      setQuantity: vi.fn(),
      variant: { productId: 'sku-s' },
      variationParams: {},
      variationAttributes: [derivedSizeAttr],
      stockLevel: 10,
      stepQuantity: 1,
      isOutOfStock: false,
      unfulfillable: false,
      isSelectedStoreOutOfStock: false,
      selectedStore: null,
    } as never);
  });

  test('sanity: our override actually rendered inside the base modal, not a crash/blank', () => {
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: vi.fn(),
      onClose: vi.fn(),
      triggerRef: { current: null },
    });

    render(
      <ProductViewModal
        product={{ id: 'test-jacket' }}
        isOpen={true}
        onClose={vi.fn()}
        addToCart={vi.fn()}
        controlledVariationValues={{ size: 'S' }}
        validateOrderability={() => true}
        showActionButtons={false}
        showImageGallery={false}
        showDeliveryOptions={false}
        showQuantityPicker={false}
      />,
    );

    // Proves the override rendered its own real Add to Bag markup inside the base modal shell —
    // not the base's own unstyled button, and not a crash swallowed into an empty modal body.
    expect(screen.getByTestId('modal-root')).toBeInTheDocument();
    expect(screen.getByTestId('zimm-add-to-bag')).toBeInTheDocument();
  });

  test('REGRESSION: clicking Add to Bag inside the base product-view-modal reaches useCartDrawer().onOpen with the real button as trigger', async () => {
    const onCartDrawerOpen = vi.fn();
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: onCartDrawerOpen,
      onClose: vi.fn(),
      triggerRef: { current: null },
    });

    render(
      <ProductViewModal
        product={{ id: 'test-jacket' }}
        isOpen={true}
        onClose={vi.fn()}
        addToCart={vi.fn().mockResolvedValue([{ itemId: 'sku-s' }])}
        controlledVariationValues={{ size: 'S' }}
        validateOrderability={() => true}
        showActionButtons={false}
        showImageGallery={false}
        showDeliveryOptions={false}
        showQuantityPicker={false}
      />,
    );

    const button = screen.getByTestId('zimm-add-to-bag');
    await userEvent.click(button);

    await waitFor(() => {
      expect(onCartDrawerOpen).toHaveBeenCalledWith(button);
    });
  });

  test('REGRESSION-NEGATIVE: does not open the cart drawer when addToCart (passed through the modal) resolves with no items added', async () => {
    const onCartDrawerOpen = vi.fn();
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: onCartDrawerOpen,
      onClose: vi.fn(),
      triggerRef: { current: null },
    });

    render(
      <ProductViewModal
        product={{ id: 'test-jacket' }}
        isOpen={true}
        onClose={vi.fn()}
        addToCart={vi.fn().mockResolvedValue(null)}
        controlledVariationValues={{ size: 'S' }}
        validateOrderability={() => true}
        showActionButtons={false}
        showImageGallery={false}
        showDeliveryOptions={false}
        showQuantityPicker={false}
      />,
    );

    await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

    expect(onCartDrawerOpen).not.toHaveBeenCalled();
  });
});

