  ModalContent: ({ children }: React.PropsWithChildren) => <div data-testid="modal-content">{children}</div>,
  ModalHeader: ({ children }: React.PropsWithChildren) => <div data-testid="modal-header">{children}</div>,
  ModalCloseButton: () => <button data-testid="modal-close">close</button>,
  ModalBody: ({ children }: React.PropsWithChildren) => <div data-testid="modal-body">{children}</div>,
