    React.cloneElement(children, { onClick: onAuthSuccess }),
}));

vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/components/responsive', () => ({
  HideOnDesktop: ({ children }: React.PropsWithChildren) => <>{children}</>,
  HideOnMobile: ({ children }: React.PropsWithChildren) => <>{children}</>,
}));

vi.mock('@salesforce/retail-react-app/app/components/quantity-picker', () => ({
  default: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
  useToast: vi.fn(() => vi.fn()),
}));

vi.mock('@salesforce/retail-react-app/app/components/display-price', () => ({
  default: () => null,
}));

