    onClick?: () => void;
    disabled?: boolean;
  }) => (
    <button
      data-testid="zimm-add-to-bag"
      aria-disabled={ariaDisabled === true ? 'true' : undefined}
      onClick={onClick}
      disabled={disabled}
    >
      {label}
    </button>
  ),
}));

const FAKE_PRODUCT = {
  id: 'test-jacket',
  productId: 'test-jacket',
  name: 'Test Jacket',
  type: { item: true },
  currency: 'AUD',
  inventory: { orderable: true, backorderable: false },
  variationAttributes: [{ id: 'size', values: [{ value: 'S', orderable: true }] }],
  variants: [],
  imageGroups: [],
};

vi.mock('@salesforce/retail-react-app/app/hooks/use-product-view-modal', () => ({
  useProductViewModal: vi.fn(() => ({
    product: FAKE_PRODUCT,
    isFetching: false,
  })),
}));

// ─── bonus-product-view-modal's own additional dependencies ───────────────────

vi.mock('@salesforce/retail-react-app/app/hooks/use-controlled-variations', () => ({
  useControlledVariations: vi.fn(() => ({
    controlledVariationValues: { size: 'S' },
    handleVariationChange: vi.fn(),
  })),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
  useCurrentBasket: vi.fn(() => ({ data: undefined, isLoading: false })),
}));

// Returning [] short-circuits handleAddToCart's own first branch
// (`if (productItems.length === 0) return null`) — sufficient for this test, since (per this
// file's own header) handleAddToCart returns null on EVERY path regardless, so there is no
// "success" branch worth additionally exercising for this specific regression question.
