  default: vi.fn(() => vi.fn()),
}));

vi.mock('@salesforce/retail-react-app/app/theme/components/project/product-view-modal', () => ({
  productViewModalTheme: {
    modal: { size: 'lg' },
    colors: { contentBackground: 'white' },
    layout: {
      content: { margin: '0', borderRadius: '0', background: 'white', overflowY: 'auto' },
      body: { background: 'white', padding: '0', paddingBottom: '0' },
    },
  },
}));

vi.mock('@salesforce/retail-react-app/app/theme/components/project/bonus-product-view-modal', () => ({
  bonusProductViewModalTheme: {
    layout: { content: { maxHeight: '90vh' } },
  },
}));

window.HTMLElement.prototype.scrollIntoView = vi.fn();

// ─── Imports that must come after the mocks above ──────────────────────────────
import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
import { useCartDrawer } from 'app/hooks/useCartDrawer';
// The BASE, unoverridden modal — imported straight from node_modules.
import BonusProductViewModal from '@salesforce/retail-react-app/app/components/bonus-product-view-modal';

const mockUseDerivedProduct = vi.mocked(useDerivedProduct);
const mockUseCartDrawer = vi.mocked(useCartDrawer);

const derivedSizeAttr = {
  id: 'size',
  name: 'Size',
  selectedValue: undefined,
  values: [{ value: 'S', name: 'S', orderable: true }],
};

describe('TESTER-6 regression: base bonus-product-view-modal + our product-view override', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockUseDerivedProduct.mockReturnValue({
      showLoading: false,
      showInventoryMessage: false,
      inventoryMessage: '',
      quantity: 1,
      minOrderQuantity: 1,
      setQuantity: vi.fn(),
      variant: { productId: 'sku-s' },
      variationParams: {},
      variationAttributes: [derivedSizeAttr],
      stockLevel: 10,
      stepQuantity: 1,
      isOutOfStock: false,
      unfulfillable: false,
      isSelectedStoreOutOfStock: false,
      selectedStore: null,
    } as never);
  });

  test('sanity: our override renders inside the base bonus-product-view-modal without crashing', () => {
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: vi.fn(),
      onClose: vi.fn(),
      triggerRef: { current: null },
    });

    render(
      <BonusProductViewModal
        product={FAKE_PRODUCT}
        isOpen={true}
        onClose={vi.fn()}
        onOpen={vi.fn()}
      />,
    );

    expect(screen.getByTestId('modal-root')).toBeInTheDocument();
    expect(screen.getByTestId('zimm-add-to-bag')).toBeInTheDocument();
  });

  test('structural finding confirmed live: clicking Add to Bag inside the bonus-product modal does NOT open the cart drawer (base\'s own handleAddToCart always resolves null — unrelated to our change, unchanged shape from base)', async () => {
    const onCartDrawerOpen = vi.fn();
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: onCartDrawerOpen,
      onClose: vi.fn(),
      triggerRef: { current: null },
    });

    render(
      <BonusProductViewModal
        product={FAKE_PRODUCT}
        isOpen={true}
        onClose={vi.fn()}
        onOpen={vi.fn()}
      />,
    );

    await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

    await waitFor(() => {
      // No crash, and no accidental leak into the shared cart drawer for a surface that base
      // itself designed to bypass the shared add-to-cart feedback path entirely.
      expect(onCartDrawerOpen).not.toHaveBeenCalled();
    });
  });
});

